/* ============================================================
   TANK COMMANDER v2 — real players (shuffled) rebuild GM
   ============================================================ */
const rnd=(a,b)=>a+Math.random()*(b-a), ri=(a,b)=>Math.floor(rnd(a,b+1));
const pick=a=>a[ri(0,a.length-1)], clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), round=Math.round;
function gauss(m,s){let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();
  return m+s*Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);}
function uid(){return Math.random().toString(36).slice(2,9);}
const $=h=>{const d=document.createElement('div');d.innerHTML=h.trim();return d.firstChild;};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));  // escape user/server strings before innerHTML
let _tt;function toast(m){let t=document.querySelector('.toast');if(t)t.remove();
  t=$(`<div class="toast"></div>`);t.textContent=m;document.body.appendChild(t);clearTimeout(_tt);_tt=setTimeout(()=>t.remove(),2400);}

