/* ---------- helpers on players ---------- */
const isPit=p=>p.pos==="SP"||p.pos==="RP";
const isHit=p=>!isPit(p);
function ovrClass(o){return o>=88?'elite':o>=80?'good':o>=70?'avg':'low';}
// 80-99 ramps yellow -> bright laser green; below that stays muted
function ovrColor(o){
  if(o<70)return 'var(--dim)';
  if(o<80)return '#cdd6bf';
  const t=clamp((o-80)/19,0,1);
  const r=Math.round(255+(166-255)*t),g=Math.round(226+(255-226)*t),b=Math.round(61+(43-61)*t);
  return `rgb(${r},${g},${b})`;
}
// Realized ceiling: scouted potential is NOT a guarantee.
// 25% reach it exactly, 60% land within 10 below, 15% within 20 below.
function rollRealCeil(pot){const r=Math.random();let rc;
  if(r<0.25)rc=pot; else if(r<0.85)rc=pot-rnd(3,10); else rc=pot-rnd(11,20);
  return Math.round(rc);}
function rollDura(age){return clamp(round(gauss(72,15)-Math.max(0,(age-31))*0.9),26,99);}
// ---- granular hidden attributes (report card) ----
const HIT_ATTRS=["contact","power","speed","eye","defense"];
const PIT_ATTRS=["velocity","control","spin","whiff"];
const ATTR_LABEL={contact:"Contact",power:"Power",speed:"Speed",eye:"Eye",defense:"Def",velocity:"Velo",control:"Ctrl",spin:"Spin",whiff:"Whiff"};
function genAttrs(pos){
  const pitcher=pos==="SP"||pos==="RP";const keys=pitcher?PIT_ATTRS:HIT_ATTRS;const bias={};
  if(!pitcher){HIT_ATTRS.forEach(k=>bias[k]=0);
    if(pos==="1B"||pos==="DH"){bias.power+=9;bias.speed-=9;bias.defense-=4;}
    else if(pos==="LF"||pos==="RF"){bias.power+=5;bias.speed-=1;bias.defense-=2;}
    else if(pos==="CF"){bias.speed+=8;bias.defense+=5;bias.power-=4;}
    else if(pos==="SS"||pos==="2B"){bias.speed+=6;bias.defense+=7;bias.power-=6;}
    else if(pos==="C"){bias.defense+=8;bias.speed-=10;}
    else if(pos==="3B"){bias.power+=3;bias.defense+=3;bias.speed-=2;}}
  const offs={};let sum=0;keys.forEach(k=>{const o=gauss(bias[k]||0,7);offs[k]=o;sum+=o;});
  const mean=sum/keys.length;keys.forEach(k=>offs[k]=Math.round(offs[k]-mean));   // center so avg ≈ OVR
  return offs;
}
function attrVal(p,k){return clamp(round((p.ovr||50)+((p.attr&&p.attr[k])||0)),20,99);}
